  tempoMap: TempoEvent[];
  meterMap: MeterEvent[];
  keyMap: KeyEvent[];
  beats: BeatEvent[];
  bars: BarEvent[];
  melody: NoteEvent[];
  /** Observed bass evidence. An empty array means no provider bass evidence was available. */
